#include "stdafx.h"#include "H_Server.h"#include <io.h>#include <CommonRSUs.h>#include "./../../HoneyWell/Include/StateSerHoneyLocal.h"#include <rsuErr.h>#include <map>#include <string>static SHParam s_params[19999];enum EKeys{  eKeyNULL     = 0,  kKeyVersion    = 0x9abc6def,};static const DWORD s_parmVer = 1;int KServer::ParamsSave( LPCSTR pszPath ){  DeleteFile( pszPath );  char drive[_MAX_DRIVE];  char dir[_MAX_DIR];  char fname[_MAX_FNAME];  char ext[_MAX_EXT];  char path_tmp[_MAX_PATH] = { 0 };  char filenameinzip[_MAX_FNAME] = { 0 };  _splitpath_s( pszPath, drive, _countof(drive), dir, _countof(dir), fname, _countof(fname), ext, _countof(ext) );  _makepath_s( filenameinzip, NULL, NULL, fname, ext );  strcpy_s( path_tmp, pszPath );  strcat_s( path_tmp, ".tmp" );  KStateSerHoneyLocal saver( path_tmp, true );  IStateSer* pSaver = saver.GetInterface();  ZeroMemory( s_params, sizeof(s_params) );  KHBridge2SysParam paramCont( s_params, _countof(s_params) );  int r = KControlBuilder::GetParams( paramCont );  saver.Write( kKeyVersion );  saver.Write( s_parmVer );  saver.Write( paramCont.Count() );  for( int i=0, C(paramCont.Count()); i<C; ++i )  {    SHParam &src = s_params[i];    saver.Write( src.ParamName );    saver.Write( src.Type );    saver.Write( src.Size );    pSaver->WriteImpl( src.pAddr, src.Size );    KKK();  }  saver.Close();  RsuPackager( path_tmp, pszPath, filenameinzip );  DeleteFile( path_tmp );  return 0;}typedef std::map<std::string, int> tLocalSortObjCont_;int KServer::ParamsRestore( LPCSTR pszPath ){  if( 0!=_access( pszPath, 0) )    return 1;  ZeroMemory( s_params, sizeof(s_params) );  KHBridge2SysParam paramCont( s_params, _countof(s_params) );  int r = KControlBuilder::GetParams( paramCont );  tLocalSortObjCont_ objs;  for( int i=0, C(paramCont.Count()); i<C; ++i )  {    SHParam &src = s_params[i];    bool add = objs.insert( tLocalSortObjCont_::value_type(src.ParamName, i) ).second;    ASS( add );  }  KStateSerHoneyLocal saver( RsuExtractor(pszPath), false );  IStateSer* pParamSer = saver.GetInterface();  EKeys key = eKeyNULL;  DWORD ver = 0;  pParamSer->Read( key );  ASS( kKeyVersion==key );  pParamSer->Read( ver );  ASS( s_parmVer==ver );  int count= 0;  pParamSer->Read( count );  char parmName[128];  BYTE type = 0;  int size = 0;  for( int i=0; i<count; ++i )  {    pParamSer->Read( parmName, _countof(parmName) );    pParamSer->Read( type );    pParamSer->Read( size );    tLocalSortObjCont_::iterator itO = objs.find( parmName );    if( objs.end()==itO )    {      ASS( size<_countof(parmName) );      pParamSer->Read( size, parmName );      continue;    }    int index = itO->second;    ASS( index < paramCont.Count() );    SHParam &src = s_params[index];    ASS( (char)type==src.Type );    ASS( size==src.Size );    pParamSer->Read( size, src.pAddr );  }  return 0;}